      const expandLines = script.match(
        /[\n;][^\n;]+=\[[^\n;]*\.\.\.[^\n;]*\][\n;]/gi
      );
      if (expandLines) {
        expandLines.forEach((line) => {
          l = line.replace(/[\n;]/gi, "");
          varName = l.split("=")[0];
          arrExpr = l
            .split("=")[1]
            .replace(/^\[|\]$/gi, "")
            .split(/,\s*/g);
          result = varName + "=[];";
          arrExpr.forEach((expr) => {
            if (/^\.\.\./i.test(expr)) {
              result +=
                varName +
                "=" +
                varName +
                ".concat(" +
                expr.replace(/^\.\.\./i, "") +
                ");";
            } else {
              result += varName + ".push(" + expr + ")";
            }
          });
          script = script.replace(line, "\n;" + result + ";\n");
